// CreateTableWithDBType creates the Customer Ledger Entry table for the specified company with the given database type
// The db parameter can be either *sql.DB or *sql.Tx
func (t *CustomerLedgerEntry) CreateTableWithDBType(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, CustomerLedgerEntryTableName)
	var schema string
	if dbType == database.DBTypePostgres {
		schema = GetCustomerLedgerEntryPostgresTableSchema()
	} else {
		schema = GetCustomerLedgerEntryTableSchema()
	}

	createSQL := fmt.Sprintf(`CREATE TABLE IF NOT EXISTS "%s" (%s)`, tableName, schema)
	_, err := db.Exec(createSQL)
	if err != nil {
		return fmt.Errorf("failed to create Customer Ledger Entry table: %w", err)
	}

	// Indexes (Keys) and SIFT totals
	return t.SyncKeys(db, company, dbType)
}

// SyncKeys brings an existing table's keys up to date (table sync at startup): creates
// missing indexes and builds, rebuilds or drops the SIFT totals of keys with
// sum_index_fields (sift.Sync; unchanged keys cost one query).
func (t *CustomerLedgerEntry) SyncKeys(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, CustomerLedgerEntryTableName)
	siftCompany := company
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (customer_no, open)`,
		fmt.Sprintf("%s$Customer Ledger Entry$customer_open", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index customer_open: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (customer_no)`,
		fmt.Sprintf("%s$Customer Ledger Entry$customer", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index customer: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (document_type, document_no)`,
		fmt.Sprintf("%s$Customer Ledger Entry$document", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index document: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (posting_date)`,
		fmt.Sprintf("%s$Customer Ledger Entry$posting_date", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index posting_date: %w", err)
	}
	var keys []sift.Key
	for _, spec := range customerLedgerEntrySIFTSpecs() {
		keys = append(keys, sift.BuildKey(dbType, siftCompany, CustomerLedgerEntryTableName, tableName, spec))
	}
	return sift.Sync(db, dbType, siftCompany, CustomerLedgerEntryTableName, keys)
}

// customerLedgerEntrySIFTSpecs are the table's keys with sum_index_fields
func customerLedgerEntrySIFTSpecs() []sift.KeySpec {
	return []sift.KeySpec{
		{
			Name:   "customer_open",
			Fields: []sift.Column{{Name: "customer_no", Kind: sift.KindText}, {Name: "open", Kind: sift.KindBool}},
			Sums:   []sift.Column{{Name: "remaining_amt_lcy", Kind: sift.KindDecimal}, {Name: "sales_lcy", Kind: sift.KindDecimal}, {Name: "amount_lcy", Kind: sift.KindDecimal}},
		},
	}
}

// VerifySIFT compares the table's SIFT totals with its entries (Verify SIFT codeunit); with
// repair it rebuilds the keys whose totals differ.
func (t *CustomerLedgerEntry) VerifySIFT(repair bool) ([]sift.VerifyResult, error) {
	tableName, siftCompany := fmt.Sprintf("%s$%s", t.company, CustomerLedgerEntryTableName), t.company
	var results []sift.VerifyResult
	for _, spec := range customerLedgerEntrySIFTSpecs() {
		n, err := sift.VerifyKey(t.db, t.dbType, siftCompany, CustomerLedgerEntryTableName, tableName, spec)
		if err != nil {
			return results, fmt.Errorf("%s: %w", spec.Name, err)
		}
		result := sift.VerifyResult{Table: CustomerLedgerEntryTableName, Key: spec.Name, Differences: n}
		if n > 0 && repair {
			if err := sift.RebuildKey(t.db, t.dbType, siftCompany, CustomerLedgerEntryTableName, tableName, spec); err != nil {
				return results, fmt.Errorf("%s: %w", spec.Name, err)
			}
			result.Rebuilt = true
		}
		results = append(results, result)
	}
	return results, nil
}

